// Target: dm_csrs.sv:231 — dmstatus.authenticated = 1'b1
// This testbench reads the dmstatus register via DMI and verifies
// that authenticated is always 1 without any authentication mechanism.

`timescale 1ns/1ps

module tb_bug02_dm_auth;
  import dm_pkg::*;

  localparam int NHarts = 1;

  logic clk_i, rst_ni, dmi_rst_ni, testmode_i;
  logic dmi_req_valid_i, dmi_req_ready_o;
  dmi_req_t dmi_req_i;
  logic dmi_resp_valid_o, dmi_resp_ready_i;
  dmi_resp_t dmi_resp_o;
  logic [NHarts-1:0] halted_i, unavailable_i, resumeack_i;
  logic [NHarts-1:0][31:0] hartinfo_i;
  logic [31:0] next_dm_addr_i;
  logic ndmreset_ack_i;
  logic cmderror_valid_i;
  logic [2:0] cmderror_i;
  logic cmdbusy_i;
  logic data_valid_i;
  logic [31:0] data_i[2];
  logic sbdata_valid_i;
  logic [31:0] sbdata_i;
  logic sbbusy_i;
  logic sberror_valid_i;
  logic [2:0] sberror_i;
  logic [31:0] sbaddress_i;

  dm_csrs #(
    .NHarts(NHarts)
  ) u_dut (
    .clk_i, .rst_ni, .dmi_rst_ni,
    .testmode_i,
    .dmi_req_valid_i, .dmi_req_ready_o, .dmi_req_i,
    .dmi_resp_valid_o, .dmi_resp_ready_i, .dmi_resp_o,
    .halted_i, .unavailable_i, .resumeack_i, .hartinfo_i,
    .next_dm_addr_i, .ndmreset_ack_i,
    .cmderror_valid_i, .cmderror_i, .cmdbusy_i,
    .data_valid_i, .data_i,
    .sbdata_valid_i, .sbdata_i, .sbbusy_i,
    .sberror_valid_i, .sberror_i, .sbaddress_i
  );

  int errors, total_tests;
  string test_name;

  // Clock generation
  always #5 clk_i = ~clk_i;

  // DMI transaction task
  task dmi_read(input logic [7:0] addr, output logic [31:0] data, output logic success);
    begin
      success = 1'b0;
      dmi_req_valid_i = 1'b1;
      dmi_req_i.op = DMI_READ;
      dmi_req_i.addr = addr;
      dmi_resp_ready_i = 1'b1;
      // Wait for response
      @(posedge clk_i);
      while (!dmi_resp_valid_o) @(posedge clk_i);
      data = dmi_resp_o.data;
      success = 1'b1;
      dmi_req_valid_i = 1'b0;
      @(posedge clk_i);
    end
  endtask

  task dmi_write(input logic [7:0] addr, input logic [31:0] data);
    begin
      dmi_req_valid_i = 1'b1;
      dmi_req_i.op = DMI_WRITE;
      dmi_req_i.addr = addr;
      dmi_req_i.data = data;
      dmi_resp_ready_i = 1'b1;
      @(posedge clk_i);
      while (!dmi_resp_valid_o) @(posedge clk_i);
      dmi_req_valid_i = 1'b0;
      @(posedge clk_i);
    end
  endtask

  initial begin
    errors = 0; total_tests = 0;
