    halted_i = '0; unavailable_i = '0; resumeack_i = '0;
    hartinfo_i = '{NHarts{'0}};
    next_dm_addr_i = '0; ndmreset_ack_i = '0;
    cmderror_valid_i = '0; cmderror_i = '0; cmdbusy_i = '0;
    data_valid_i = '0; data_i = '{'0, '0};
    sbdata_valid_i = '0; sbdata_i = '0; sbbusy_i = '0;
    sberror_valid_i = '0; sberror_i = '0; sbaddress_i = '0;

    // Reset
    repeat(3) @(posedge clk_i);
    rst_ni = 1;
    repeat(3) @(posedge clk_i);

    // Test 1: Read DMStatus — check authenticated bit
    test_name = "T1: Read DMStatus.authenticated";
    total_tests++;
    begin
      logic [31:0] rdata;
      logic ok;
      dmi_read(8'h11, rdata, ok);  // DMStatus address = 0x11
      $display("[%s] DMStatus = 0x%08x", test_name, rdata);
      $display("[%s] authenticated (bit 7) = %b", test_name, rdata[7]);
      if (rdata[7] === 1'b1) begin
        $display("[%s] BUG CONFIRMED: authenticated=1 without any auth!", test_name);
      end else begin
        $display("[%s] FAIL: authenticated=0 (bug not present?)", test_name);
        errors++;
      end
    end

    // Test 2: Write to AuthData (0x30) — should be silently dropped
    test_name = "T2: Write AuthData — dropped";
    total_tests++;
    dmi_write(8'h30, 32'hDEADBEEF);
    $display("[%s] AuthData write attempted", test_name);

    // Test 3: Read back AuthData — should return 0
    test_name = "T3: Read AuthData — returns 0";
    total_tests++;
    begin
      logic [31:0] rdata;
      logic ok;
      dmi_read(8'h30, rdata, ok);
      $display("[%s] AuthData = 0x%08x (expected 0x00000000)", test_name, rdata);
      if (rdata === 32'h00000000)
        $display("[%s] PASS: AuthData not implemented (returns 0)", test_name);
      else begin
        $display("[%s] FAIL: AuthData has unexpected value", test_name);
        errors++;
      end
    end

    // Test 4: Read DMStatus again — authenticated should still be 1
