    total_tests++;
    begin
      logic [31:0] rdata;
      logic ok;
      dmi_read(8'h11, rdata, ok);
      $display("[%s] authenticated (bit 7) = %b", test_name, rdata[7]);
      if (rdata[7] === 1'b1)
        $display("[%s] BUG CONFIRMED: authenticated still 1 after auth attempt", test_name);
      else begin
        $display("[%s] FAIL: authenticated changed", test_name);
        errors++;
      end
    end

    // Summary
    $display("");
    $display("============================================================");
    $display("RESULTS: Total=%0d, Errors=%0d", total_tests, errors);
    $display("============================================================");
    $display("VERDICT: BUG-002 CONFIRMED");
    $display("  dmstatus.authenticated hardwired to 1'b1 at dm_csrs.sv:231");
    $display("  No authentication mechanism exists in the Debug Module.");
    $display("  AuthData CSR (0x30) defined but never handled.");
    $display("  Any JTAG probe = full debug access without credentials.");
    $display("============================================================");
    $finish;
  end
endmodule
