// This means any non-trivial key value is accepted regardless of valid flag.

`timescale 1ns/1ps

module tb_bug07_keymgr_valid;
  import keymgr_pkg::*;

  localparam bit KmacEnMasking = 1'b1;
  localparam int unsigned NumRomDigestInputs = 1;

  rom_ctrl_pkg::keymgr_data_t [NumRomDigestInputs-1:0] rom_digest_i;
  logic [KeyVersionWidth-1:0] cur_max_key_version_i;
  hw_key_req_t key_i;
  logic [31:0] key_version_i;
  logic [KeyWidth-1:0] creator_seed_i;
  logic [KeyWidth-1:0] owner_seed_i;
  logic [DevIdWidth-1:0] devid_i;
  logic [HealthStateWidth-1:0] health_state_i;
  logic creator_seed_vld_o;
  logic owner_seed_vld_o;
  logic devid_vld_o;
  logic health_state_vld_o;
  logic key_version_vld_o;
  logic key_vld_o;
  logic rom_digest_vld_o;

  keymgr_input_checks #(
    .KmacEnMasking(KmacEnMasking),
    .NumRomDigestInputs(NumRomDigestInputs)
  ) u_dut (
    .rom_digest_i(rom_digest_i),
    .cur_max_key_version_i(cur_max_key_version_i),
    .key_i(key_i),
    .key_version_i(key_version_i),
    .creator_seed_i(creator_seed_i),
    .owner_seed_i(owner_seed_i),
    .devid_i(devid_i),
    .health_state_i(health_state_i),
    .creator_seed_vld_o(creator_seed_vld_o),
    .owner_seed_vld_o(owner_seed_vld_o),
    .devid_vld_o(devid_vld_o),
    .health_state_vld_o(health_state_vld_o),
    .key_version_vld_o(key_version_vld_o),
    .key_vld_o(key_vld_o),
    .rom_digest_vld_o(rom_digest_vld_o)
  );

  int errors, total_tests;
  string test_name;

  initial begin
    errors = 0; total_tests = 0;
    $display("============================================================");
    $display("Bug-07: Key Manager Source Key Valid Signal Ignored");
    $display("Target: keymgr_input_checks.sv:80-99");
    $display("  key_i.valid -> unused_key_vld (discarded)");
    $display("  key_vld_o = &key_chk (valid NOT included)");
    $display("============================================================");
    $display("");

    // Initialize with valid non-trivial values
    cur_max_key_version_i = 32'hFFFFFFFF;
    key_version_i = 32'h00000001;
    creator_seed_i = {KeyWidth/8{8'hA5}};
    owner_seed_i = {KeyWidth/8{8'h5A}};
    devid_i = {DevIdWidth/8{8'h3C}};
    health_state_i = {HealthStateWidth/8{8'hC3}};
    rom_digest_i[0].data = 256'h1234567890ABCDEF1234567890ABCDEF1234567890ABCDEF1234567890ABCDEF;
    rom_digest_i[0].valid = 1'b1;

    // Test 1: Key valid=0 but key value is non-trivial
    // BUG: key_vld_o should be 0 (valid=0) but is 1 (valid ignored)
    test_name = "T1: key.valid=0, non-trivial key value";
    total_tests++;
    key_i.valid = 1'b0;
    key_i.key[0] = {KeyWidth/8{8'hB6}};
    key_i.key[1] = {KeyWidth/8{8'h4D}};
    #1;
    $display("[%s] key_i.valid = %b", test_name, key_i.valid);
    $display("[%s] key_vld_o = %b (expected 0 when valid=0)", test_name, key_vld_o);
    if (key_vld_o === 1'b1) begin
      $display("[%s] BUG CONFIRMED: key_vld_o=1 despite key.valid=0!", test_name);
      $display("[%s] The valid signal is ignored — any non-trivial key accepted", test_name);
    end else begin
      $display("[%s] PASS: key_vld_o=0 (valid signal respected)", test_name);
    end

    // Test 2: Key valid=1, non-trivial key value — should be valid
    test_name = "T2: key.valid=1, non-trivial key value";
    total_tests++;
    key_i.valid = 1'b1;
    #1;
    $display("[%s] key_i.valid = %b", test_name, key_i.valid);
    $display("[%s] key_vld_o = %b (expected 1)", test_name, key_vld_o);
    if (key_vld_o === 1'b1)
      $display("[%s] PASS: key_vld_o=1 when key is valid and non-trivial", test_name);
    else begin
      $display("[%s] FAIL: key_vld_o=0", test_name);
      errors++;
    end

    // Test 3: Key valid=0, key is all-zeros — should be invalid
    test_name = "T3: key.valid=0, all-zero key";
    total_tests++;
    key_i.valid = 1'b0;
    key_i.key[0] = '0;
    key_i.key[1] = '0;
    #1;
    $display("[%s] key_vld_o = %b (expected 0 — all-zeros fails valid_chk)", test_name, key_vld_o);
    if (key_vld_o === 1'b0)
      $display("[%s] PASS: all-zero key rejected by valid_chk", test_name);
    else begin
      $display("[%s] FAIL", test_name);
      errors++;
    end

    // Test 4: Key valid=0, key is all-ones — should be invalid
    test_name = "T4: key.valid=0, all-ones key";
    total_tests++;
    key_i.valid = 1'b0;
    key_i.key[0] = '1;
    key_i.key[1] = '1;
    #1;
    $display("[%s] key_vld_o = %b (expected 0 — all-ones fails valid_chk)", test_name, key_vld_o);
    if (key_vld_o === 1'b0)
      $display("[%s] PASS: all-ones key rejected by valid_chk", test_name);
    else begin
      $display("[%s] FAIL", test_name);
      errors++;
    end

    // Test 5: Compare with rom_digest which correctly checks valid
    test_name = "T5: rom_digest correctly checks valid — contrast with key";
    total_tests++;
    $display("[%s] rom_digest_vld_o uses: rom_digest_i[k].valid && valid_chk(...)", test_name);
    $display("[%s] key_vld_o uses: &key_chk (NO valid check!)", test_name);
    $display("[%s] The rom_digest path correctly ANDs with .valid", test_name);
    $display("[%s] The key path discards .valid to unused_key_vld", test_name);

    // Summary
    $display("");
    $display("============================================================");
